      backup_text =
        "# Night Garden Nutrient Tracker #\n\
         # Soil management for the night garden #\n\n\
         # Soil nutrients are measured 0-100 #\n\
         # N = Nitrogen, P = Phosphorus, K = Potassium #\n\
         type Soil = (\n\
         n = Int,\n\
         p = Int,\n\
         k = Int\n\
         ) in\n\n\
         # Crops of the night garden #\n\
         type Crop =\n\
         + Duskwheat      # Nitrogen fixer - restores N when harvested #\n\
         + Moonmelon        # Heavy feeder - depletes N significantly #\n\
         + Starfruit    # Balanced - moderate use of all nutrients #\n\
         + Nightshade  # Cover crop - restores N when turned under #\n\
         in\n\n\
         # A garden plot tracks soil, current crop (if any), and season #\n\
         type Model = (\n\
         soil = Soil,\n\
         crop = +None +Some(Crop),\n\
         season = Int\n\
         ) in\n\n\
         # Actions that can be performed on a plot #\n\
         type Action =\n\
         + Plant(Crop)\n\
         + Harvest\n\
         + Compost         # Add organic matter, boosts all nutrients #\n\
         + SeasonChange    # Time passes, nutrients settle #\n\
         in\n\n\
         # Utility: clamp value between 0 and 100 #\n\
         let clamp : Int -> Int =\n\
         fun x ->\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         # Initial balanced soil - good starting conditions #\n\
         let balancedSoil : Soil = (n = 60, p = 60, k = 60) in\n\n\
         # Create a fresh plot with balanced soil #\n\
         let initModel : Model = (\n\
         soil = balancedSoil,\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\n\
         # Calculate how a crop affects soil when planted #\n\
         # Planting takes a small amount of nutrients to establish #\n\
         let plantingCost : (Soil, Crop) -> Soil =\n\
         fun (s, crop) ->\n\
         case crop\n\
         | Duskwheat => (n = s.n, p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         | Moonmelon => (n = clamp(s.n - 5), p = clamp(s.p - 5), k = clamp(s.k \
         - 5))\n\
         | Starfruit => (n = clamp(s.n - 5), p = clamp(s.p - 5), k = clamp(s.k \
         - 5))\n\
         | Nightshade => (n = s.n, p = clamp(s.p - 3), k = clamp(s.k - 3))\n\
         end\n\
         in\n\n\
         # Calculate how a crop affects soil when harvested #\n\
         # This is the main nutrient exchange - crops deplete or restore #\n\
         let harvestEffect : (Soil, Crop) -> Soil =\n\
         fun (s, crop) ->\n\
         case crop\n\
         | Duskwheat =>\n\
         # Nitrogen fixer: restores N, uses some P and K #\n\
         (n = clamp(s.n + 15), p = clamp(s.p - 10), k = clamp(s.k - 10))\n\
         | Moonmelon =>\n\
         # Heavy N feeder: depletes N significantly #\n\
         (n = clamp(s.n - 30), p = clamp(s.p - 10), k = clamp(s.k - 15))\n\
         | Starfruit =>\n\
         # Balanced consumer: moderate depletion across all #\n\
         (n = clamp(s.n - 15), p = clamp(s.p - 15), k = clamp(s.k - 15))\n\
         | Nightshade =>\n\
         # Cover crop: major N restoration when turned under #\n\
         (n = clamp(s.n + 20), p = clamp(s.p - 5), k = clamp(s.k - 5))\n\
         end\n\
         in\n\n\
         # Apply compost - boosts all nutrients #\n\
         let applyCompost : Soil -> Soil =\n\
         fun s ->\n\
         (n = clamp(s.n + 10), p = clamp(s.p + 10), k = clamp(s.k + 10))\n\
         in\n\n\
         # Season change - minor settling/leaching #\n\
         let seasonSettle : Soil -> Soil =\n\
         fun s ->\n\
         (n = clamp(s.n - 3), p = clamp(s.p - 2), k = clamp(s.k - 2))\n\
         in\n\n\
         # Main update function #\n\
         let update : (Model, Action) -> Model =\n\
         fun (p, action) ->\n\
         case action\n\
         | Plant(crop) =>\n\
         case p.crop\n\
         | Some(_) => p  # Can't plant if crop already growing #\n\
         | None =>\n\
         (\n\
         soil = plantingCost(p.soil, crop),\n\
         crop = Some(crop),\n\
         season = p.season\n\
         )\n\
         end\n\
         | Harvest =>\n\
         case p.crop\n\
         | None => p  # Nothing to harvest #\n\
         | Some(crop) =>\n\
         (\n\
         soil = harvestEffect(p.soil, crop),\n\
         crop = None,\n\
         season = p.season\n\
         )\n\
         end\n\
         | Compost =>\n\
         (\n\
         soil = applyCompost(p.soil),\n\
         crop = p.crop,\n\
         season = p.season\n\
         )\n\
         | SeasonChange =>\n\
         (\n\
         soil = seasonSettle(p.soil),\n\
         crop = p.crop,\n\
         season = p.season + 1\n\
         )\n\
         end\n\
         in\n\n\
         # Run multiple actions in sequence #\n\
         let farm : (Model, [Action]) -> Model =\n\
         fun (plot, actions) ->\n\
         fold_left(actions, update, plot)\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         # Basic planting tests #\n\
         hint \"planting sets the current crop\"\n\
         test\n\
         let p = update(initModel, Plant(Moonmelon)) in\n\
         p.crop == Some(Moonmelon)\n\
         end;\n\n\
         hint \"cannot plant when crop already growing\"\n\
         test\n\
         let p = farm(initModel, [Plant(Moonmelon), Plant(Starfruit)]) in\n\
         p.crop == Some(Moonmelon)\n\
         end;\n\n\
         hint \"planting has small nutrient cost\"\n\
         test\n\
         let p = update(initModel, Plant(Starfruit)) in\n\
         p.soil.n < initModel.soil.n\n\
         end;\n\n\
         # Harvest tests #\n\
         hint \"harvesting clears the crop\"\n\
         test\n\
         let p = farm(initModel, [Plant(Moonmelon), Harvest]) in\n\
         p.crop == None\n\
         end;\n\n\
         hint \"harvesting nothing changes nothing\"\n\
         test\n\
         let p = update(initModel, Harvest) in\n\
         p == initModel\n\
         end;\n\n\
         # Crop-specific effects #\n\
         hint \"moonmelon depletes nitrogen heavily\"\n\
         test\n\
         let p = farm(initModel, [Plant(Moonmelon), Harvest]) in\n\
         p.soil.n < initModel.soil.n - 20\n\
         end;\n\n\
         hint \"duskwheat restores nitrogen\"\n\
         test\n\
         let depleted = (\n\
         soil = (n = 30, p = 50, k = 50),\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\
         let p = farm(depleted, [Plant(Duskwheat), Harvest]) in\n\
         p.soil.n > depleted.soil.n\n\
         end;\n\n\
         hint \"nightshade restores nitrogen significantly\"\n\
         test\n\
         let depleted = (\n\
         soil = (n = 30, p = 60, k = 60),\n\
         crop = None,\n\
         season = 1\n\
         ) in\n\
         let p = farm(depleted, [Plant(Nightshade), Harvest]) in\n\
         p.soil.n >= 45  # Started at 30, should gain 20 minus small planting \
         cost #\n\
         end;\n\n\
         hint \"starfruit depletes all nutrients moderately\"\n\
         test\n\
         let p = farm(initModel, [Plant(Starfruit), Harvest]) in\n\
         p.soil.n < initModel.soil.n &&\n\
         p.soil.p < initModel.soil.p &&\n\
         p.soil.k < initModel.soil.k\n\
         end;\n\n\
         # Compost tests #\n\
         hint \"compost boosts all nutrients\"\n\
         test\n\
         let p = update(initModel, Compost) in\n\
         p.soil.n > initModel.soil.n &&\n\
         p.soil.p > initModel.soil.p &&\n\
         p.soil.k > initModel.soil.k\n\
         end;\n\n\
         hint \"compost respects maximum (100)\"\n\
         test\n\
         let rich = (soil = (n = 95, p = 95, k = 95), crop = None, season = 1) \
         in\n\
         let p = update(rich, Compost) in\n\
         p.soil.n == 100 && p.soil.p == 100 && p.soil.k == 100\n\
         end;\n\n\
         # Season change tests #\n\
         hint \"season advances counter\"\n\
         test\n\
         let p = update(initModel, SeasonChange) in\n\
         p.season == 2\n\
         end;\n\n\
         hint \"season change causes minor nutrient loss\"\n\
         test\n\
         let p = update(initModel, SeasonChange) in\n\
         p.soil.n < initModel.soil.n\n\
         end;\n\n\
         # Crop rotation scenario #\n\
         hint \"moonmelon then nightshade rotation restores nitrogen\"\n\
         test\n\
         let start = (soil = (n = 60, p = 60, k = 60), crop = None, season = \
         1) in\n\
         let afterMoonmelon = farm(start, [Plant(Moonmelon), Harvest]) in\n\
         let afterClover = farm(afterMoonmelon, [Plant(Nightshade), Harvest]) in\n\
         afterClover.soil.n > afterMoonmelon.soil.n &&\n\
         afterClover.soil.n >= 40\n\
         end;\n\n\
         # Nutrients stay in valid range #\n\
         hint \"nutrients cannot go below 0\"\n\
         test\n\
         let poor = (soil = (n = 10, p = 10, k = 10), crop = None, season = 1) \
         in\n\
         let p = farm(poor, [Plant(Moonmelon), Harvest]) in\n\
         p.soil.n >= 0 && p.soil.p >= 0 && p.soil.k >= 0\n\
         end;\n\n\
         hint \"nutrients cannot exceed 100\"\n\
         test\n\
         let rich = (soil = (n = 90, p = 90, k = 90), crop = None, season = 1) \
         in\n\
         let p = farm(rich, [Compost, Compost, Compost]) in\n\
         p.soil.n <= 100 && p.soil.p <= 100 && p.soil.k <= 100\n\
         end;\n\n\
         # Full season demo #\n\
         farm(initModel, [\n\
         # Spring: plant moonmelon (heavy feeder) #\n\
         Plant(Moonmelon),\n\
         SeasonChange,\n\
         Harvest,\n\
         # Summer: follow with nightshade to restore N #\n\
         Plant(Nightshade),\n\
         SeasonChange,\n\
         Harvest,\n\
         # Fall: add compost, plant duskwheat #\n\
         Compost,\n\
         Plant(Duskwheat),\n\
         SeasonChange,\n\
         Harvest\n\
         ])\n";
      refractors = "()";
    } )
